-- Migration 079: historical speaker/prayer import + a new
-- speaker_prayer_history_import table + informational people notes.
--
-- One-time bulk import of the ward's real "Speaker & Prayer History"
-- spreadsheet, pasted/attached directly by the user 2026-10-21 -- see
-- PROJECT_CONTEXT.md's Known open items for the full context. Mapped and
-- generated by a one-off local script (parsed the raw .xlsx by hand,
-- PowerShell XML parsing -- no pandas/openpyxl available in this
-- environment -- then reformatted every "Last, First Middle" name to
-- "First Middle Last" in that script, matching this repo's own
-- established convention that name reformatting happens in the
-- throwaway script, never in SQL; person matching itself still happens
-- here, in SQL, against whatever people rows actually exist when this
-- runs -- same case-insensitive WHERE NOT EXISTS idiom as migrations
-- 049/067).
--
-- Decisions made directly with the user before this was written:
--   - The Prayer History sheet has no column distinguishing Opening vs.
--     Closing Prayer -- every row imports as a single generic 'prayer'
--     role, not split.
--   - The sheet's Notes Database (per-person flags like "Inactive,"
--     "Won't Speak," "Won't Pray," "Lives outside of ward") imports as
--     purely informational speaking_note/praying_note text on people --
--     never used to filter who shows up on the app's own due-lists.
--
-- Three sheets were deliberately NOT imported: Adult/Youth/Prayers (the
-- spreadsheet's own "Instructions" sheet confirms these are
-- script-regenerated read-only report views, not source data), All
-- Members (has birthdate/phone/email -- conflicts with this app's own
-- documented no-bulk-PII-import policy), and On Radar for Prayers
-- (undated, ephemeral scratch notes).
--
-- A handful of exact duplicate (name, date) rows within the sheet's own
-- Speaker History / Prayer History tabs (e.g. "Jack Taylor Beutler"
-- entered twice for 2025-10-19) were deduplicated by the generating
-- script before this file was written -- kept once each, not twice.
--
-- Two name clusters below are genuinely AMBIGUOUS -- possibly the same
-- person recorded two different ways, possibly two different real
-- people -- and were deliberately left as separate `people` rows rather
-- than guessed at and merged (merging two different real people's
-- histories together would be a worse mistake than one harmless extra
-- row the user can clean up by hand in Table Admin):
--   - "Nixon J Rappleye" vs. "Nixon Rappleye"
--   - "Karleen Annick Le Tendre" vs. "Karleen LeTendre" vs. "Karissa LeTendre"
-- One single-character typo WAS corrected with confidence, not left
-- ambiguous: "Braxton Merrit" (one row, Prayer History) -> "Braxton
-- Merritt," matching every other occurrence of this same person
-- elsewhere in both sheets.
--
-- Idempotent throughout (create/alter ... if not exists, insert ...
-- where not exists) since partial-failure re-runs are common in this
-- project's own history.

create table if not exists speaker_prayer_history_import (
  id uuid primary key default gen_random_uuid(),
  person_id uuid not null references people(id),
  role text not null check (role in ('speaker', 'prayer')),
  occurred_on date not null,
  notes text,
  source text not null default 'historical_import',
  created_at timestamptz not null default now()
);

alter table speaker_prayer_history_import enable row level security;

drop policy if exists "authenticated access" on speaker_prayer_history_import;
create policy "authenticated access"
  on speaker_prayer_history_import for all
  to authenticated
  using (true)
  with check (true);

-- Table Admin feature catalog row -- raw-data fallback, same
-- "bespoke page for everyday use" convention as sacrament_speakers_adults.
-- Nobody gets it automatically; grant it via /admin/calling-features.
insert into features (key, label, category, sort_order) values
  ('table_admin_speaker_prayer_history_import', 'Speaker & Prayer History (Import)', 'Table Admin', 23)
on conflict (key) do nothing;

alter table people add column if not exists speaking_note text;
alter table people add column if not exists praying_note text;

