join people p on lower(trim(p.name)) = lower(trim(v.name))
where not exists (
  select 1
  from sacrament_speakers_adults sa
  join meetings m on m.id = sa.meeting_id
  where sa.speaker_id = p.id and sa.confirmed = true and m.date = v.occurred_on
)
and not exists (
  select 1
  from sacrament_speakers_youth sy
  join meetings m on m.id = sy.meeting_id
  where sy.speaker_id = p.id and sy.confirmed = true and m.date = v.occurred_on
)
and not exists (
  select 1 from speaker_prayer_history_import existing
  where existing.person_id = p.id and existing.role = 'speaker' and existing.occurred_on = v.occurred_on
);

-- Prayer History rows -- same dedup approach, against sacrament_assignments'
