  join meetings m on m.id = sa.meeting_id
  where sa.assigned_to_id = p.id
    and sa.role in ('opening_prayer', 'closing_prayer')
    and m.date = v.occurred_on
)
and not exists (
  select 1 from speaker_prayer_history_import existing
  where existing.person_id = p.id and existing.role = 'prayer' and existing.occurred_on = v.occurred_on
);

